protocolTypes.tsDefinition:
| {
    type: 'runtime_diagnostics_snapshot';
    diagnostics_version: 1;
    request_id: string;
    snapshot: {
      process: {
        profile_binding: 'unknown' | 'default_home' | 'explicit_home' | 'bound_profile' | 'unbound_profile';
        engine_mode: 'unknown' | 'standard' | 'raw';
        workspace_kind: 'unknown' | 'none' | 'project' | 'temporary' | 'profile_home';
        profile_name?: string;
      };
      config_sources: Array<{
        role: 'global' | 'project' | 'profile' | 'cli' | 'environment' | 'credential_store' | 'desktop_launch';
        disposition: 'loaded' | 'absent' | 'ignored' | 'unreadable' | 'invalid' | 'overridden' | 'restricted';
        precedence: number;
        content_digest?: string;
        display_path?: string;
      }>;
      unsupported_overrides: Array<{
        name: string;
        disposition: 'loaded' | 'absent' | 'ignored' | 'unreadable' | 'invalid' | 'overridden' | 'restricted';
      }>;
      mcp_servers: Array<{
        name: string;
        origin: 'effective_config' | 'global_config' | 'project_config' | 'profile_config' | 'runtime_command' | 'plugin';
        transport: 'stdio' | 'sse' | 'streamable_http';
        connection: 'configured' | 'deferred' | 'connecting' | 'ready' | 'failed' | 'timed_out' | 'skipped' | 'stopping' | 'stopped';
        exposure: 'not_attempted' | 'not_applicable' | 'exposed' | 'resource_only' | 'resource_only_unavailable' | 'hidden_no_tools' | 'blocked';
        deferred: boolean;
        tool_count: number;
        resources_declared: boolean;
        resources_exposed: boolean;
        assistant_scoped: boolean;
        executable_readiness:
          | 'not_applicable'
          | 'unchecked'
          | 'resolved'
          | 'missing_effective_path'
          | 'not_found'
          | 'invalid_absolute_path'
          | 'invalid_executable'
          | 'invalid_effective_environment'
          | 'permission_denied'
          | 'not_executable'
          | 'probe_timed_out'
          | 'unsupported_transport';
        working_directory: 'inherited_process' | 'project_root' | 'profile_home' | 'explicit';
        remediation: Array<
          | 'open_active_config'
          | 'restart_desktop'
          | 'fix_gui_launch_path'
          | 'install_executable'
          | 'fix_executable_permissions'
          | 'review_server_config'
          | 'retry_connection'
          | 'retry_diagnostics'
          | 'check_assistant_scope'
          | 'restart_to_load_resources'
        >;
        executable_basename?: string;
        failure?:
          | 'missing_executable'
          | 'launch_failed'
          | 'connection_refused'
          | 'timeout'
          | 'protocol_mismatch'
          | 'authentication_required'
          | 'authorization_denied'
          | 'invalid_configuration'
          | 'transport_closed'
          | 'unknown';
      }>;
    };
  }

| {
    type: 'runtime_diagnostics_unavailable';
    /** The version the HOST asked for. Schema: integer 0..65535 - NOT const 1. */
    diagnostics_version: number;
    /** The only version this engine can serve. Schema: const 1. */
    supported_version: 1;
    request_id: string;
    reason: 'unsupported_version' | 'invalid_request';
  }

| {
    type: 'mcp_removal_result';
    /** Schema: integer 0..65535 - NOT const 1. Fixture value is 1. */
    lifecycle_version: number;
    request_id: string;
    name: string;
    /**
     * Free-form in BOTH core-event.schema.json and producer-complete.schema.json:
     * `{"type":"string"}` with no enum. The only value the contract exhibits is
     * 'removed'. Do NOT narrow this to a union - see risks.
     */
    outcome: string;
    removed_tools: string[];
  }

| {
    type: 'get_runtime_diagnostics';
    /** Schema: const 1. The host cannot legally ask for any other version. */
    diagnostics_version: 1;
    /** 1..128 chars. additionalProperties:false - send nothing else. */
    request_id: string;
  }

| {
    type: 'remove_mcp_server';
    /** Schema: integer 0..65535. Send the module constant 1 (the fixture value). */
    lifecycle_version: number;
    /** 1..256 chars AND x-maxUtf8Bytes:256. additionalProperties:false. */
    request_id: string;
    /** 1..256 chars AND x-maxUtf8Bytes:256 - byte cap, not code-unit cap. */
    name: string;
  }
